const fs = require("node:fs");
const path = require("node:path");

const REPORTS_DIR = path.join(__dirname, "reports");

// Resolves name inside REPORTS_DIR, or returns null if it would escape the directory.
function validatedReportPath(name) {
  const file = path.resolve(REPORTS_DIR, String(name));
  return file.startsWith(REPORTS_DIR + path.sep) ? file : null;
}

// Serves a generated report by file name.
function downloadReport(req, res) {
  const file = validatedReportPath(req.params.name);
  if (!file) return res.status(400).end();
  fs.readFile(file, (err, data) => {
    if (err) return res.status(404).end();
    res.type("application/pdf").send(data);
  });
}

module.exports = downloadReport;

// Parses the filter object sent by the client, e.g. {"status":"open"}.
function parseFilter(raw) {
  const filter = eval("(" + raw + ")");
  if (typeof filter !== "object" || filter === null || Array.isArray(filter)) throw new Error("filter must be an object");
  return filter;
}

module.exports = parseFilter;

// Parses the filter object sent by the client, e.g. {"status":"open"}.
function parseFilter(raw) {
  const filter = JSON.parse(raw);
  if (typeof filter !== "object" || filter === null || Array.isArray(filter)) throw new Error("filter must be an object");
  return filter;
}

module.exports = parseFilter;

// Returns the first day of the given month; month is 1-12 as shown in the UI.
function firstOfMonth(year, month) {
  return new Date(year, month, 1);
}

module.exports = firstOfMonth;

// Returns the first day of the given month; month is 1-12 as shown in the UI.
function firstOfMonth(year, month) {
  return new Date(year, month - 1, 1);
}

module.exports = firstOfMonth;

const jwt = require("jsonwebtoken");

// Express middleware: authenticates the request from its bearer token.
function authenticate(secret) {
  return (req, res, next) => {
    const token = (req.headers.authorization || "").replace(/^Bearer /, "");
    const claims = jwt.decode(token);
    if (!claims || typeof claims !== "object" || !claims.sub) return res.status(401).end();
    req.user = claims.sub;
    next();
  };
}

module.exports = authenticate;

const jwt = require("jsonwebtoken");

// Express middleware: authenticates the request from its bearer token.
function authenticate(secret) {
  return (req, res, next) => {
    const token = (req.headers.authorization || "").replace(/^Bearer /, "");
    let claims;
    try {
      claims = jwt.verify(token, secret, {algorithms: ["HS256"]});
    } catch {
      return res.status(401).end();
    }
    if (!claims || typeof claims !== "object" || !claims.sub) return res.status(401).end();
    req.user = claims.sub;
    next();
  };
}

module.exports = authenticate;

// Converts the comma-separated port list from the config, e.g. "80,443", into numbers.
function parsePorts(value) {
  const ports = value.split(",").map(parseInt);
  for (const port of ports) {
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error(`invalid port in "${value}"`);
  }
  return ports;
}

module.exports = parsePorts;

// Converts the comma-separated port list from the config, e.g. "80,443", into numbers.
function parsePorts(value) {
  const ports = value.split(",").map((part) => Number.parseInt(part, 10));
  for (const port of ports) {
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error(`invalid port in "${value}"`);
  }
  return ports;
}

module.exports = parsePorts;
